/**
 * Parameter types for each tool, mapped by tool name
 */
export type ToolParams = {
  [NOTE_BACKLINKS]: NoteBacklinksParams;
  [NOTE_ATTACHMENTS]: NoteAttachmentsParams;
  [NOTE_BEGIN_UPLOAD]: NoteBeginUploadParams;
  [NOTE_DOWNLOAD]: NoteDownloadParams;
  [NOTE_COMPLETE_UPLOAD]: NoteCompleteUploadParams;
  [NOTE_FILE_ATTACHMENT]: NoteFileAttachmentParams;
  [NOTE_REFERENCES]: NoteReferencesParams;
  [NOTE_ADD_REFERENCE]: NoteAddReferenceParams;
  [NOTE_REMOVE_REFERENCE]: NoteRemoveReferenceParams;
  [TICKET_BACKLINKS]: TicketBacklinksParams;
  [TICKET_ATTACHMENTS]: TicketAttachmentsParams;
  [TICKET_BEGIN_UPLOAD]: TicketBeginUploadParams;
  [TICKET_REMOVE_ATTACHMENT]: TicketRemoveAttachmentParams;
  [TICKET_DOWNLOAD]: TicketDownloadParams;
  [TICKET_COMPLETE_UPLOAD]: TicketCompleteUploadParams;
  [TICKET_FILE_ATTACHMENT]: TicketFileAttachmentParams;
  [TICKET_REFERENCES]: TicketReferencesParams;
  [TICKET_ADD_REFERENCE]: TicketAddReferenceParams;
  [TICKET_REMOVE_REFERENCE]: TicketRemoveReferenceParams;
  [TICKET_GET_TICKET]: TicketGetTicketParams;
};

/**
 * Invokes a tool by name using the SDK. A tool whose bindingStatus is
 * unsupported_multipart uploads a file, which tool parameters cannot carry;
 * invokeTool throws for it without sending a request.
 *
 * @param sdk - The initialized SDK instance
 * @param toolName - The namespaced tool name (e.g., "auth.sendMagicLink")
 * @param params - The parameters for the tool
 * @returns The result of the tool invocation
 * @throws Error if the tool name is not recognized
 *
 * @example
 * ```typescript
 * const sdk = new FixtureReferencesApiSDK({ baseUrl: 'https://api.example.com' });
 * const result = await invokeTool(sdk, 'auth.sendMagicLink', { email: 'user@example.com' });
 * ```
 */
export async function invokeTool<T extends ToolName>(
  sdk: FixtureReferencesApiSDK,
  toolName: T,
  params: ToolParams[T]
): Promise<unknown> {
  switch (toolName) {
    case NOTE_BACKLINKS:
      return sdk.note.backlinks((params as NoteBacklinksParams).id);
    case NOTE_ATTACHMENTS:
      return sdk.note.attachments((params as NoteAttachmentsParams).id);
    case NOTE_BEGIN_UPLOAD:
      return sdk.note.beginUpload((params as NoteBeginUploadParams).id, { name: (params as NoteBeginUploadParams).name, mediaType: (params as NoteBeginUploadParams).mediaType, size: (params as NoteBeginUploadParams).size, sha256: (params as NoteBeginUploadParams).sha256, caption: (params as NoteBeginUploadParams).caption });
    case NOTE_DOWNLOAD:
      return sdk.note.download((params as NoteDownloadParams).id, (params as NoteDownloadParams).file);
    case NOTE_COMPLETE_UPLOAD:
      return sdk.note.completeUpload((params as NoteCompleteUploadParams).id, (params as NoteCompleteUploadParams).file);
    case NOTE_FILE_ATTACHMENT:
      return sdk.note.fileAttachment((params as NoteFileAttachmentParams).id, (params as NoteFileAttachmentParams).file, { to: (params as NoteFileAttachmentParams).to, move: (params as NoteFileAttachmentParams).move, role: (params as NoteFileAttachmentParams).role });
    case NOTE_REFERENCES:
      return sdk.note.references((params as NoteReferencesParams).id);
    case NOTE_ADD_REFERENCE:
      return sdk.note.addReference((params as NoteAddReferenceParams).id, { to: (params as NoteAddReferenceParams).to, role: (params as NoteAddReferenceParams).role });
    case NOTE_REMOVE_REFERENCE:
      return sdk.note.removeReference((params as NoteRemoveReferenceParams).id, { to: (params as NoteRemoveReferenceParams).to, role: (params as NoteRemoveReferenceParams).role });
    case TICKET_BACKLINKS:
      return sdk.ticket.backlinks((params as TicketBacklinksParams).id);
    case TICKET_ATTACHMENTS:
      return sdk.ticket.attachments((params as TicketAttachmentsParams).id);
    case TICKET_BEGIN_UPLOAD:
      return sdk.ticket.beginUpload((params as TicketBeginUploadParams).id, { name: (params as TicketBeginUploadParams).name, mediaType: (params as TicketBeginUploadParams).mediaType, size: (params as TicketBeginUploadParams).size, sha256: (params as TicketBeginUploadParams).sha256, caption: (params as TicketBeginUploadParams).caption });
    case TICKET_REMOVE_ATTACHMENT:
      return sdk.ticket.removeAttachment((params as TicketRemoveAttachmentParams).id, (params as TicketRemoveAttachmentParams).file);
    case TICKET_DOWNLOAD:
      return sdk.ticket.download((params as TicketDownloadParams).id, (params as TicketDownloadParams).file);
    case TICKET_COMPLETE_UPLOAD:
      return sdk.ticket.completeUpload((params as TicketCompleteUploadParams).id, (params as TicketCompleteUploadParams).file);
    case TICKET_FILE_ATTACHMENT:
      return sdk.ticket.fileAttachment((params as TicketFileAttachmentParams).id, (params as TicketFileAttachmentParams).file, { to: (params as TicketFileAttachmentParams).to, move: (params as TicketFileAttachmentParams).move, role: (params as TicketFileAttachmentParams).role });
    case TICKET_REFERENCES:
      return sdk.ticket.references((params as TicketReferencesParams).id);
    case TICKET_ADD_REFERENCE:
      return sdk.ticket.addReference((params as TicketAddReferenceParams).id, { to: (params as TicketAddReferenceParams).to, role: (params as TicketAddReferenceParams).role });
    case TICKET_REMOVE_REFERENCE:
      return sdk.ticket.removeReference((params as TicketRemoveReferenceParams).id, { to: (params as TicketRemoveReferenceParams).to, role: (params as TicketRemoveReferenceParams).role });
    case TICKET_GET_TICKET:
      return sdk.ticket.getTicket((params as TicketGetTicketParams).id);
    default:
      throw new Error(`Unknown tool: ${toolName}`);
  }
}

/**
 * Gets the tool definition for a given tool name
 */
export function getToolDefinition(toolName: ToolName): ToolDefinition {
  return toolDefinitions[toolName];
}

/**
 * Gets all tools that require authentication
 */
export function getAuthRequiredTools(): ToolDefinition[] {
  return Object.values(toolDefinitions).filter(t => t.requiresAuth);
}

/**
 * Gets all tools that don't require authentication
 */
export function getPublicTools(): ToolDefinition[] {
  return Object.values(toolDefinitions).filter(t => !t.requiresAuth);
}

/**
 * Gets all tools for a specific namespace
 */
export function getToolsForNamespace(namespace: string): ToolDefinition[] {
  return Object.values(toolDefinitions).filter(t => t.namespace === namespace);
}

/**
 * Validates that params contain all required fields for a tool
 */
export function validateToolParams(toolName: ToolName, params: Record<string, unknown>): { valid: boolean; missing: string[] } {
  const tool = toolDefinitions[toolName];
  const required = tool.parameters.required || [];
  const missing = required.filter(field => !(field in params) || params[field] === undefined);
  return { valid: missing.length === 0, missing };
}
